import fs from 'fs';
import {Client} from '@modelcontextprotocol/sdk/client/index.js';
import {StreamableHTTPClientTransport} from '@modelcontextprotocol/sdk/client/streamableHttp.js';
const D=process.env.D; const t=JSON.parse(fs.readFileSync(D+'/maria-token.json','utf8'));
const tok=t.token||t.value||t.access_token||Object.values(t).find(v=>typeof v==='string'&&v.startsWith('done_'));
const c=new Client({name:'maria-agent',version:'1'});
await c.connect(new StreamableHTTPClientTransport(new URL('http://localhost:8810/mcp'),{requestInit:{headers:{Authorization:'Bearer '+tok}}}));
const calls=JSON.parse(process.argv[2]);
for(const [n,a] of calls){const r=await c.callTool({name:n,arguments:a||{}});console.log('##',n,new Date().toISOString());console.log(r.content.map(x=>x.text).join('\n'));}
await c.close();
EOF
export D; node done2-maria-call.mjs '[["whoami"],["my_limits"]]'

